== .kiro/hooks/guard-no-physical-targets.json
{
  "version": "v1",
  "hooks": [
    {
      "name": "Guard: no physical Modbus targets",
      "description": "Blocks (exit 2) writes to csharp/** that add a non-loopback IPv4 literal, 0.0.0.0, or a TcpClient/ConnectAsync host taken from request JSON. Fails open with a warning if the event cannot be parsed.",
      "trigger": "PreToolUse",
      "matcher": "^(fs_write|fs_append|str_replace)$",
      "action": {
        "type": "command",
        "command": "python3 tools/hooks/guard_targets.py"
      },
      "timeout": 30
    }
  ]
}

== .kiro/hooks/run-tests-after-csharp-change.json
{
  "version": "v1",
  "hooks": [
    {
      "name": "Run tests after C# change",
      "description": "When the agent saves a csharp/**/*.cs file, run the GhostWire test harness and report the last 60 lines (exit code preserved) back to the agent.",
      "trigger": "PostFileSave",
      "matcher": "(^|/)csharp/.*\\.cs$",
      "action": {
        "type": "command",
        "command": "bash -c 'set -o pipefail; tools/dotnet run --project csharp/GhostWire.Tests/GhostWire.Tests.csproj 2>&1 | tail -n 60'"
      },
      "timeout": 300
    }
  ]
}

== .kiro/hooks/scenario-docs-sync.json
{
  "version": "v1",
  "hooks": [
    {
      "name": "Sync judge quick start with scenarios",
      "trigger": "PostFileSave",
      "description": "After the agent saves Training.cs, asks the agent to update docs/judge-quick-start.md if scenario definitions changed.",
      "matcher": "(^|/)csharp/GhostWire/Training\\.cs$",
      "action": {
        "type": "agent",
        "prompt": "csharp/GhostWire/Training.cs was just saved. Run `git diff -- csharp/GhostWire/Training.cs` and check whether the scenario definitions changed: the `Cases` array (id, title, summary, initial settings, documentation, unit, function, address, value, requiredScale) or any added or removed scenario. If they did not change, do nothing and say so in one line. If they changed, update docs/judge-quick-start.md so every step matches the current scenarios: case titles, initial settings, the symptom the first read shows, the documented fix, and the expected verified result. Use only values the simulator actually produces (run the test harness if unsure) and keep the existing safety sentences. Do not edit any other file for this hook."
      }
    }
  ]
}
== .kiro/hooks/stop-verify.json
{
  "version": "v1",
  "hooks": [
    {
      "name": "Verify build on stop",
      "description": "Runs `tools/dotnet build csharp/GhostWire/GhostWire.csproj -v q -nologo` when the agent stops. Only on build errors it prints {\"decision\":\"block\",\"reason\":\"<errors>\"} so the agent continues and fixes them.",
      "trigger": "Stop",
      "action": {
        "type": "command",
        "command": "python3 tools/hooks/stop_build_check.py"
      },
      "timeout": 180
    }
  ]
}

