const frameInfo = await evaluate(`({ hex: Array.from(document.querySelectorAll('#frames .hex')).map(h => h.textContent), heads: Array.from(document.querySelectorAll('#frames thead th')).slice(0,3).map(t => t.textContent + '/' + t.scope), terms: Array.from(document.querySelectorAll('#wire-evidence dt')).map(d => d.textContent), font: getComputedStyle(document.querySelector('#frames .hex')).fontFamily })`);
check(frameInfo.hex[0] === '00 01 00 00 00 06 07 03 00 0A 00 01' && frameInfo.hex[1] === '00 01 00 00 00 05 07 03 02 00 27', 'frame hex rendered from server', JSON.stringify(frameInfo.hex));
check(frameInfo.heads.join(',') === 'Field/col,Bytes (hex)/col,Decoded value/col', 'frame table header cells', frameInfo.heads.join(','));
check(frameInfo.terms.join(',') === 'MBAP header,PDU,Unit ID,Function code', 'terms defined', frameInfo.terms.join(','));
check(/mono|Consolas/i.test(frameInfo.font), 'hex uses a monospace font', frameInfo.font);

