check(await evaluate(`document.getElementById('log-note').textContent.includes('carry no client identity')`), 'capture note shown');
check(await evaluate(`Array.from(document.querySelectorAll('#log-table thead th')).every(t => t.scope === 'col')`), 'log table header cells');
await evaluate(`document.getElementById('run-test').click()`);
check(await waitFor(`document.getElementById('test-message').textContent.startsWith('Read complete')`), 'phantom read completes');
