await evaluate(`document.querySelectorAll('#log-body tr')[${writeIndex}].querySelector('summary').focus()`);
await key('Tab', 'Tab');
check(await evaluate(`document.activeElement.textContent === 'Select'`), 'Select button reachable by keyboard');
await key('Enter', 'Enter');
await evaluate(`document.getElementById('submit-answer').focus()`);
const focusBefore = await evaluate(`document.activeElement.id`);
await key('Enter', 'Enter');
check(await waitFor(`document.getElementById('test-message').textContent.startsWith('Answer verified')`), 'verified answer announced in status region');
check(await evaluate(`document.activeElement.id`) === focusBefore, 'focus not moved by the announcement');
const flag = await evaluate(`(() => { const r = document.querySelector('#log-body tr[data-flag="unauthorized"]'); return r && { text: r.querySelector('.flag').textContent, tab: r.tabIndex, border: getComputedStyle(r.firstElementChild).borderLeftStyle, mit: document.querySelectorAll('#answer-mitigations li').length, heading: document.querySelector('#mitigations-section h3').textContent }; })()`);
check(flag && flag.text === '⚠ Unauthorized write' && flag.tab === 0 && flag.border === 'double', 'verified answer flags the row with text, icon, pattern and tabindex', JSON.stringify(flag));
check(flag && flag.mit === 4 && flag.heading === 'Next steps · real-world guidance, not verified by this simulation', 'four labeled mitigations');
await evaluate(`document.querySelector('#log-body tr[data-flag]').previousElementSibling.querySelector('button').focus()`);
let flagReached = false;
for (let i = 0; i < 4 && !flagReached; i++) { await key('Tab', 'Tab'); flagReached = await evaluate(`document.activeElement.dataset?.flag === 'unauthorized'`); }
check(flagReached, 'flagged row reachable with Tab');
check(await evaluate(`document.querySelectorAll('#answer-history > li').length === 2 && !document.getElementById('print-report').disabled`), 'answer attempts in case history');

// Reduced motion.
await send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-reduced-motion', value: 'reduce' }] });
check(await evaluate(`getComputedStyle(document.querySelector('.hex span')).transitionDuration === '0s'`), 'prefers-reduced-motion disables transitions', await evaluate(`getComputedStyle(document.querySelector('.hex span')).transitionDuration`));
await send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-reduced-motion', value: 'no-preference' }] });
check(await evaluate(`getComputedStyle(document.querySelector('.hex span')).transitionDuration !== '0s'`), 'transition present without reduced motion');

// Print media.
await evaluate(`window.dispatchEvent(new Event('beforeprint'))`);
await send('Emulation.setEmulatedMedia', { media: 'print' });
const print = await evaluate(`({ incident: getComputedStyle(document.getElementById('incident-panel')).display, history: getComputedStyle(document.querySelector('.history')).display, answersOpen: Array.from(document.querySelectorAll('#answer-history details')).every(d => d.open), answerText: document.getElementById('answer-history').innerText.slice(0, 120) })`);
check(print.incident === 'none' && print.history !== 'none' && print.answersOpen && print.answerText.includes('Answer 1'), 'print report includes answer attempts', JSON.stringify(print));
const pdf = await send('Page.printToPDF', {});
check(!!pdf.result?.data, 'print to PDF renders', `${pdf.result?.data?.length ?? 0} base64 chars`);

console.log(results.join('\n'));
console.log(`${results.filter((r) => r.startsWith('PASS')).length} passed, ${results.filter((r) => r.startsWith('FAIL')).length} failed`);
ws.close(); proc.kill();
process.exit(results.some((r) => r.startsWith('FAIL')) ? 1 : 0);

