// Temporary manual UI check for GhostWire (not part of the repository). Drives headless Chrome over CDP.
import { spawn } from 'node:child_process';
import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const chrome = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const port = 9333;
const proc = spawn(chrome, ['--headless=new', `--remote-debugging-port=${port}`, `--user-data-dir=${mkdtempSync(join(tmpdir(), 'gwchrome-'))}`, '--no-first-run', 'about:blank'], { stdio: 'ignore' });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let targets;
for (let i = 0; i < 50; i++) { try { targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json(); break; } catch { await sleep(200); } }
const page = targets.find((t) => t.type === 'page');
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => ws.addEventListener('open', r));
let id = 0; const pending = new Map();
ws.addEventListener('message', (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } });
const send = (method, params = {}) => new Promise((r) => { const n = ++id; pending.set(n, r); ws.send(JSON.stringify({ id: n, method, params })); });
const evaluate = async (expression) => { const m = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true }); if (m.result.exceptionDetails) throw new Error(JSON.stringify(m.result.exceptionDetails)); return m.result.result.value; };
const results = [];
const check = (ok, name, detail = '') => { results.push(`${ok ? 'PASS' : 'FAIL'} ${name}${detail ? ` :: ${detail}` : ''}`); };
const key = async (k, code, shift = false) => {
  const keyCode = { Tab: 9, Enter: 13, ' ': 32 }[k];
  await send('Input.dispatchKeyEvent', { type: 'keyDown', key: k, code, windowsVirtualKeyCode: keyCode, modifiers: shift ? 8 : 0, text: k === 'Enter' ? '\r' : undefined });
  await send('Input.dispatchKeyEvent', { type: 'keyUp', key: k, code, windowsVirtualKeyCode: keyCode, modifiers: shift ? 8 : 0 });
};
const waitFor = async (expr, ms = 5000) => { const t = Date.now(); while (Date.now() - t < ms) { if (await evaluate(expr)) return true; await sleep(50); } return false; };

await send('Page.enable'); await send('Runtime.enable');
await send('Page.navigate', { url: 'http://127.0.0.1:8000/' });
check(await waitFor(`document.querySelectorAll('#scenario option').length === 4`), 'scenarios loaded');
const groups = await evaluate(`Array.from(document.querySelectorAll('#scenario optgroup')).map(g => g.label + ': ' + Array.from(g.children).map(o => o.textContent).join(' | '))`);
check(groups.length === 2 && groups[0].startsWith('Troubleshooting:') && groups[1] === 'Security incidents: Phantom Writer · intermediate', 'grouped picker with difficulty text', JSON.stringify(groups));
check(await evaluate(`document.getElementById('incident-panel').hidden`), 'incident panel hidden for a troubleshooting case');

// Giant Pressure read and Wire evidence.
await evaluate(`document.getElementById('run-test').click()`);
check(await waitFor(`document.getElementById('test-message').textContent.startsWith('Read complete')`), 'pressure read completes');
check(await evaluate(`!document.getElementById('wire-evidence').open`), 'Wire evidence collapsed by default');
const frameInfo = await evaluate(`({ hex: Array.from(document.querySelectorAll('#frames .hex')).map(h => h.textContent), heads: Array.from(document.querySelectorAll('#frames thead th')).slice(0,3).map(t => t.textContent + '/' + t.scope), terms: Array.from(document.querySelectorAll('#wire-evidence dt')).map(d => d.textContent), font: getComputedStyle(document.querySelector('#frames .hex')).fontFamily })`);
check(frameInfo.hex[0] === '00 01 00 00 00 06 07 03 00 0A 00 01' && frameInfo.hex[1] === '00 01 00 00 00 05 07 03 02 00 27', 'frame hex rendered from server', JSON.stringify(frameInfo.hex));
check(frameInfo.heads.join(',') === 'Field/col,Bytes (hex)/col,Decoded value/col', 'frame table header cells', frameInfo.heads.join(','));
check(frameInfo.terms.join(',') === 'MBAP header,PDU,Unit ID,Function code', 'terms defined', frameInfo.terms.join(','));
check(/mono|Consolas/i.test(frameInfo.font), 'hex uses a monospace font', frameInfo.font);

// Keyboard: Tab to the Wire evidence summary, open it with Enter, Tab into a field row.
await evaluate(`document.getElementById('run-test').focus()`);
let reached = false;
for (let i = 0; i < 40 && !reached; i++) { await key('Tab', 'Tab'); reached = await evaluate(`document.activeElement === document.querySelector('#wire-evidence > summary')`); }
check(reached, 'Wire evidence summary reachable with Tab');
await key('Enter', 'Enter');
check(await evaluate(`document.getElementById('wire-evidence').open`), 'Enter opens Wire evidence');
const rowVisit = [];
for (let i = 0; i < 6; i++) {
  await key('Tab', 'Tab');
  rowVisit.push(await evaluate(`(() => { const a = document.activeElement; if (a.tagName !== 'TR') return a.tagName + ':' + a.textContent.slice(0,30); const range = document.getElementById(a.getAttribute('aria-describedby')).textContent.trim(); const frame = a.closest('.frame'); const hl = Array.from(frame.querySelectorAll('.hex span.hl')).map(s => s.dataset.i).join(','); return a.querySelector('th').textContent + ' | ' + range + ' | hl=' + hl + ' | deco=' + getComputedStyle(frame.querySelector('.hex span.hl') || frame).textDecorationLine; })()`));
}
check(rowVisit[0].startsWith('Transaction ID | bytes 0–1 | hl=0,1 | deco=underline'), 'focusing a field row highlights its bytes with underline and states the range', rowVisit[0]);
check(rowVisit.some((r) => r.startsWith('Unit ID | byte 6 | hl=6')), 'single-byte field range text', rowVisit.join(' || '));

// Silent Sensor timeout: one request frame.
await evaluate(`(() => { const s = document.getElementById('scenario'); s.value = 'unit-id'; s.dispatchEvent(new Event('change')); document.getElementById('run-test').click(); })()`);
check(await waitFor(`document.getElementById('test-message').textContent.startsWith('Read complete')`), 'silent sensor read completes');
check(await evaluate(`document.getElementById('result-status').textContent === 'Status: timeout' && document.querySelectorAll('#frames .frame').length === 1`), 'timeout shows Status text and one request frame');

// Phantom Writer.
await evaluate(`(() => { const s = document.getElementById('scenario'); s.value = 'phantom-writer'; s.dispatchEvent(new Event('change')); })()`);
check(await waitFor(`document.querySelectorAll('#log-body tr').length === 12`), 'traffic log shows 12 rows');
check(await evaluate(`!document.getElementById('incident-panel').hidden && document.querySelectorAll('#log-body tr[data-flag]').length === 0 && !document.body.textContent.includes('Unauthorized write')`), 'no row is flagged before a verified answer');
check(await evaluate(`document.getElementById('log-note').textContent.includes('carry no client identity')`), 'capture note shown');
check(await evaluate(`Array.from(document.querySelectorAll('#log-table thead th')).every(t => t.scope === 'col')`), 'log table header cells');
await evaluate(`document.getElementById('run-test').click()`);
check(await waitFor(`document.getElementById('test-message').textContent.startsWith('Read complete')`), 'phantom read completes');
check(await evaluate(`document.getElementById('engineering-value').textContent === '95 °C' && document.getElementById('raw-registers').textContent === '950'`), 'phantom read shows 95 °C and raw 950', await evaluate(`document.getElementById('engineering-value').textContent`));

// Wrong answer via the Select button of row 3.
await evaluate(`document.querySelectorAll('#log-body tr')[2].querySelector('button').click()`);
check(await evaluate(`document.getElementById('answer-transaction').value === '3' && document.getElementById('answer-client').value === 'HMI-01'`), 'Select fills the answer form');
await evaluate(`document.getElementById('submit-answer').click()`);
check(await waitFor(`document.getElementById('test-message').textContent.startsWith('Answer not verified')`), 'wrong answer announced in status region');
check(await evaluate(`document.getElementById('mitigations-section').hidden && document.querySelectorAll('#log-body tr[data-flag]').length === 0 && document.getElementById('answer-status').textContent === 'Status: answer not verified'`), 'wrong answer: no mitigations, no flag, text status');

// Keyboard path to the FC06 row's Select button and submit.
const writeIndex = await evaluate(`Array.from(document.querySelectorAll('#log-body tr')).findIndex(r => r.children[5].textContent.startsWith('06'))`);
await evaluate(`document.querySelectorAll('#log-body tr')[${writeIndex}].querySelector('summary').focus()`);
await key('Tab', 'Tab');
check(await evaluate(`document.activeElement.textContent === 'Select'`), 'Select button reachable by keyboard');
await key('Enter', 'Enter');
await evaluate(`document.getElementById('submit-answer').focus()`);
const focusBefore = await evaluate(`document.activeElement.id`);
await key('Enter', 'Enter');
check(await waitFor(`document.getElementById('test-message').textContent.startsWith('Answer verified')`), 'verified answer announced in status region');
check(await evaluate(`document.activeElement.id`) === focusBefore, 'focus not moved by the announcement');
const flag = await evaluate(`(() => { const r = document.querySelector('#log-body tr[data-flag="unauthorized"]'); return r && { text: r.querySelector('.flag').textContent, tab: r.tabIndex, border: getComputedStyle(r.firstElementChild).borderLeftStyle, mit: document.querySelectorAll('#answer-mitigations li').length, heading: document.querySelector('#mitigations-section h3').textContent }; })()`);
check(flag && flag.text === '⚠ Unauthorized write' && flag.tab === 0 && flag.border === 'double', 'verified answer flags the row with text, icon, pattern and tabindex', JSON.stringify(flag));
check(flag && flag.mit === 4 && flag.heading === 'Next steps · real-world guidance, not verified by this simulation', 'four labeled mitigations');
await evaluate(`document.querySelector('#log-body tr[data-flag]').previousElementSibling.querySelector('button').focus()`);
let flagReached = false;
for (let i = 0; i < 4 && !flagReached; i++) { await key('Tab', 'Tab'); flagReached = await evaluate(`document.activeElement.dataset?.flag === 'unauthorized'`); }
check(flagReached, 'flagged row reachable with Tab');
check(await evaluate(`document.querySelectorAll('#answer-history > li').length === 2 && !document.getElementById('print-report').disabled`), 'answer attempts in case history');

// Reduced motion.
await send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-reduced-motion', value: 'reduce' }] });
check(await evaluate(`getComputedStyle(document.querySelector('.hex span')).transitionDuration === '0s'`), 'prefers-reduced-motion disables transitions', await evaluate(`getComputedStyle(document.querySelector('.hex span')).transitionDuration`));
await send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-reduced-motion', value: 'no-preference' }] });
check(await evaluate(`getComputedStyle(document.querySelector('.hex span')).transitionDuration !== '0s'`), 'transition present without reduced motion');

// Print media.
await evaluate(`window.dispatchEvent(new Event('beforeprint'))`);
await send('Emulation.setEmulatedMedia', { media: 'print' });
const print = await evaluate(`({ incident: getComputedStyle(document.getElementById('incident-panel')).display, history: getComputedStyle(document.querySelector('.history')).display, answersOpen: Array.from(document.querySelectorAll('#answer-history details')).every(d => d.open), answerText: document.getElementById('answer-history').innerText.slice(0, 120) })`);
check(print.incident === 'none' && print.history !== 'none' && print.answersOpen && print.answerText.includes('Answer 1'), 'print report includes answer attempts', JSON.stringify(print));
const pdf = await send('Page.printToPDF', {});
check(!!pdf.result?.data, 'print to PDF renders', `${pdf.result?.data?.length ?? 0} base64 chars`);

console.log(results.join('\n'));
console.log(`${results.filter((r) => r.startsWith('PASS')).length} passed, ${results.filter((r) => r.startsWith('FAIL')).length} failed`);
ws.close(); proc.kill();
process.exit(results.some((r) => r.startsWith('FAIL')) ? 1 : 0);

